let $=jQuery;function initializeCarousel(elementId,numColumnsDesktop,numColumnsTablet,numColumnsMobile,numSpaceTablet,numSpaceMobile,customArrows,wrapper,slidesToScroll){if(numColumnsDesktop===0||numColumnsTablet===0||numColumnsMobile===0){return!1}
let wrapperClass="";if(wrapper){wrapperClass=wrapper}
let carouselDiv=$("#"+elementId+" "+wrapperClass);if(carouselDiv.length>1){slides=$(carouselDiv[carouselDiv.length-1]).children(".wpb_column")}else{slides=$(carouselDiv).children(".wpb_column")}
let desktopConfig={slidesToShow:numColumnsDesktop,slidesToScroll:slidesToScroll,dots:slides.length>numColumnsDesktop,arrows:slides.length>numColumnsDesktop,};let slickOptions={autoplay:!1,infinite:!1,mobileFirst:!0,slidesToShow:numColumnsMobile+numSpaceMobile,slidesToScroll:1,dots:!0,arrows:customArrows,centerMode:!1,prevArrow:'#cos-nav-arrows-'+elementId+' .cos-long-arrow.left',nextArrow:'#cos-nav-arrows-'+elementId+' .cos-long-arrow.right',slide:'div',responsive:[{breakpoint:576,settings:{slidesToShow:numColumnsTablet+numSpaceTablet,slidesToScroll:slidesToScroll,},},{breakpoint:991,settings:slides.length<=numColumnsDesktop?"unslick":desktopConfig,},],};if(carouselDiv.length>1){carousel=$(carouselDiv[carouselDiv.length-1]).slick(slickOptions)}else{carousel=$(carouselDiv).slick(slickOptions)}
disableArrows(customArrows,slides,numColumnsDesktop,elementId);setSameHeightColumns(carousel);$(carouselDiv).on('setPosition',function(element){setSameHeightColumns(element.target)});$(window).on('resize orientationchange',function(){if(!carouselDiv[0].classList.contains('slick-initialized')){disableArrows(customArrows,slides,numColumnsDesktop,elementId);const carouselElement=$(carouselDiv[0]).slick(slickOptions)}})}
function disableArrows(customArrows,slides,numColumnsDesktop,elementId){if(customArrows){if(slides.length<=numColumnsDesktop){if(window.innerWidth>=991){$('#cos-nav-arrows-'+elementId).find('.cos-long-arrow').css("display","none");$('#cos-nav-arrows-'+elementId).find('.cos-long-arrow').css("display","none")}else{$('#cos-nav-arrows-'+elementId).find('.cos-long-arrow').css("display","block");$('#cos-nav-arrows-'+elementId).find('.cos-long-arrow').css("display","block")}}}}
function setSameHeightColumns(container){let highestColumn=0;let columns=$(container).find('.slick-slide');columns.each(function(){$(this).height('auto');if($(this).height()>highestColumn){highestColumn=$(this).height()}});columns.height(highestColumn)}